}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args _args)
{
    AVAERPriceListToAzureBlobController       controller;
    AVAERPriceListToAzureBlobContract         dataContract;
    SysOperationStartResult                   sysOperationStartResult;

    if (!_args)
    {
        throw error("@SYS25407");
    }

    controller  = new AVAERPriceListToAzureBlobController();
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    controller.parmClassName(classStr(AVAERPriceListToAzureBlobService));
    controller.parmMethodName(methodStr(AVAERPriceListToAzureBlobService, runService));
    controller.parmDialogCaption("@NDX:NXAPriceIncreaseCreatePriceLists");

    dataContract    = controller.getDataContractObject();

    if (_args && _args.record())
    {
        FormRun                 formRun = _args.caller();
        FormDataSource          fds_priceDiscGroup = formRun.dataSource(formDataSourceStr(AVAPriceIncreaseTable,PriceDiscGroup));
        FormDataSource          fds_priceIncreaseTable = formRun.dataSource(formDataSourceStr(AVAPriceIncreaseTable,AVAPriceIncreaseTable));
        AVAPriceIncreaseTable   avaPriceIncreaseTable = fds_priceIncreaseTable.cursor();
        MultiSelectionHelper    helper = MultiSelectionHelper::construct();
        PriceDiscGroup          priceDiscGroup;
        String255               priceGroupFilterStr;

        helper.parmDatasource(fds_priceDiscGroup);

        priceDiscGroup = helper.getFirst();
        while (priceDiscGroup.RecId != 0)
        {
            if (priceGroupFilterStr != '')
            {
                priceGroupFilterStr += ',';
            }
            priceGroupFilterStr +=  priceDiscGroup.GroupId;
            priceDiscGroup = helper.getNext();
        }
        dataContract.parmpriceGroupFilterStr(priceGroupFilterStr);
        dataContract.parmPriceIncreaseSet(avaPriceIncreaseTable.PriceIncreaseSet);
    }

    sysOperationStartResult = controller.startOperation();

    if(sysOperationStartResult == SysOperationStartResult::Started)
    {
        info(strFmt("@SYS82282", "@NDX:NXAOperationStarted"));
    }
}
